import { useEffect, useState } from "react";
import { Link } from "react-router-dom";

import Layout from "./Layout.jsx";

function Dashboard({ search, setSearch }) {

  const [notes, setNotes] = useState([]);
  const [filter, setFilter] = useState("recent");
  const [category, setCategory] = useState("all");
 
  const [noteQuestions, setNoteQuestions] = useState({});

  const user = JSON.parse(localStorage.getItem("user") || "null");



  useEffect(() => {
    fetch("http://localhost:5000/api/notes")
      .then((res) => res.json())
      .then((data) => setNotes(data))
      .catch((err) => console.log(err));
  }, []);

  
  const filteredNotes = notes.filter((n) => {
    const s = search?.toLowerCase() || "";
    return n.title?.toLowerCase().includes(s) || n.topic?.toLowerCase().includes(s);
  });

  const handleNoteQuestion = async (noteId, noteTitle) => {
    const question = noteQuestions[noteId];
    if (!question?.trim()) {
      alert("Please type a question first");
      return;
    }
    try {
      const res = await fetch("http://localhost:5000/api/questions/json", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          title: question,
          description: `Question about note: "${noteTitle}"`,
          category: "notes",
          postedBy: user?.name,
          role: user?.role,
        }),
      });
      if (res.ok) {
        alert("Question posted successfully!");
        setNoteQuestions((prev) => ({ ...prev, [noteId]: "" }));
        fetch("http://localhost:5000/api/questions")
          .then((r) => r.json())
          .then((data) => setQuestions(data));
      } else {
        alert("Failed to post question");
      }
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <Layout
      filter={filter}
      setFilter={setFilter}
      category={category}
      setCategory={setCategory}
      search={search}
      setSearch={setSearch}
    >
      <div className="header">
        <div>
          <h2>Dashboard</h2>
          <p>
            {activeTab === "posts" ? filtered.length : filteredNotes.length} available
          </p>
        </div>
        <Link to="/ask" className="new-post">+ New Post</Link>
      </div>

      <div style={{ display: "flex", gap: "8px", marginBottom: "20px" }}>
        <button
          onClick={() => setActiveTab("posts")}
          style={{
            padding: "8px 24px", borderRadius: "8px", border: "none",
            cursor: "pointer", fontWeight: "600", fontSize: "14px",
            background: activeTab === "posts" ? "#16a34a" : "#f0f0f0",
            color: activeTab === "posts" ? "white" : "#555",
          }}
        >
          📋 Posts
        </button>
        <button
          onClick={() => setActiveTab("notes")}
          style={{
            padding: "8px 24px", borderRadius: "8px", border: "none",
            cursor: "pointer", fontWeight: "600", fontSize: "14px",
            background: activeTab === "notes" ? "#16a34a" : "#f0f0f0",
            color: activeTab === "notes" ? "white" : "#555",
          }}
        >
          📄 Notes
        </button>
      </div>

      {activeTab === "posts" && (
        <div>
          {filtered.length === 0 ? (
            <p>No posts available</p>
          ) : (
            filtered.map((q) => (
              <div key={q._id} className="post">
                <div className="post-top">
                  <div className="user">
                    <div className="avatar small">
                      {q.postedBy?.[0]?.toUpperCase() || "U"}
                    </div>
                    <div>
                      <b>{q.postedBy}</b>
                      <p style={{ margin: 0, fontSize: "12px" }}>{q.role}</p>
                    </div>
                  </div>
                  <span className="tag">{q.category}</span>
                </div>
                <h3>{q.title}</h3>
                <div className="post-bottom">
                  <span>❤️ {q.likes?.length || 0}</span>
                  <Link to={`/answers/${q._id}`} className="view-btn">
                    View →
                  </Link>
                </div>
              </div>
            ))
          )}
        </div>
      )}

      {activeTab === "notes" && (
        <div>
          {filteredNotes.length === 0 ? (
            <p>No notes available</p>
          ) : (
            filteredNotes.map((note) => (
              <div key={note._id} className="post">
                <div className="post-top">
                  <div className="user">
                    <div className="avatar small">
                      {note.uploadedBy?.[0]?.toUpperCase() || "U"}
                    </div>
                    <div>
                      <b>{note.uploadedBy}</b>
                      <p style={{ margin: 0, fontSize: "12px" }}>Senior</p>
                    </div>
                  </div>
                  <span className="tag">{note.topic}</span>
                </div>

                <h3>{note.title}</h3>

<div className="post-bottom">
  
    <a>href={"http://localhost:5000/uploads/" + note.file}
    target="_blank"
    rel="noreferrer"
    className="view-btn"
  
    📥 Download
  </a>
</div>

                <div style={{ marginTop: "12px", borderTop: "1px solid #eee", paddingTop: "12px" }}>
                  <p style={{ margin: "0 0 8px", fontSize: "13px", color: "#555", fontWeight: "600" }}>
                    💬 Ask a question about this note
                  </p>
                  <div style={{ display: "flex", gap: "8px" }}>
                    <input
                      type="text"
                      placeholder="Type your question here..."
                      value={noteQuestions[note._id] || ""}
                      onChange={(e) =>
                        setNoteQuestions((prev) => ({ ...prev, [note._id]: e.target.value }))
                      }
                      style={{
                        flex: 1, padding: "8px 12px",
                        borderRadius: "8px", border: "1px solid #ddd", fontSize: "13px",
                      }}
                    />
                    <button
                      onClick={() => handleNoteQuestion(note._id, note.title)}
                      style={{
                        padding: "8px 16px", background: "#16a34a",
                        color: "white", border: "none", borderRadius: "8px",
                        cursor: "pointer", fontWeight: "600", fontSize: "13px",
                      }}
                    >
                      Ask
                    </button>
                  </div>
                </div>
              </div>
      ))
          )}
    </div>
  )
}
    </Layout >
  );
}

export default Dashboard;
